 { 
 CLSID clsid; 
 ::CLSIDFromProgID(L"SldWorks.Application", 
 &clsid); 

 ISldWorks *swApp = NULL; 
 ::CoCreateInstance(clsid, NULL, CLSCTX_LOCAL_SERVER, 
 __uuidof(ISldWorks), (void**)&swApp); 
 if (swApp != NULL) 
 { 
 BSTR bstrHello = ::SysAllocString(L"Hello 
 from SOLIDWORKS."); 
